              { tipo: 'codigo', p: 'Limpe os espaços das pontas, deixe em MAIÚSCULAS e mostre com o tamanho:<pre>CORTE E ESCOVA tem 14 letras</pre>', inicio: `const entrada = "   corte e escova  ";\n`, saida: 'CORTE E ESCOVA tem 14 letras', dicas: ['const limpo = entrada.trim().toUpperCase();', 'Use limpo.length para o tamanho', 'console.log(`${limpo} tem ${limpo.length} letras`);'], sol: `const entrada = "   corte e escova  ";\nconst limpo = entrada.trim().toUpperCase();\nconsole.log(\`\${limpo} tem \${limpo.length} letras\`);` }
