              { titulo: 'Convertendo a resposta', texto: `<p>Como a resposta é texto, use <code>Number()</code> antes de fazer contas.</p>`, codigo: `const idade = Number(prompt("Idade: "));\nconsole.log(\`Em 10 anos: \${idade + 10}\`);`, entrada: '20' }
