              { tipo: 'codigo', p: 'Leia o <b>nome</b> e o <b>ano de nascimento</b> (nessa ordem, com prompt) e mostre a idade em 2026:<pre>Nome: Rafa\nAno: 2000\nRafa faz 26 anos em 2026</pre>', inicio: `const nome = prompt("Nome: ");\n`, entrada: 'Rafa\n2000', saida: 'Nome: Rafa\nAno: 2000\nRafa faz 26 anos em 2026', dicas: ['const ano = Number(prompt("Ano: "));', 'A idade é 2026 - ano', 'console.log(`${nome} faz ${2026 - ano} anos em 2026`);'], sol: `const nome = prompt("Nome: ");\nconst ano = Number(prompt("Ano: "));\nconsole.log(\`\${nome} faz \${2026 - ano} anos em 2026\`);` }
