              { titulo: 'break e continue', texto: `<p><code>break</code> sai do laço. <code>continue</code> pula para a próxima volta.</p>`, codigo: `let n = 0;\nwhile (true) {\n  n++;\n  if (n === 2) continue;\n  if (n > 4) break;\n  console.log(n);\n}` }
