              { tipo: 'prever', codigo: `let total = 0, n = 1;\nwhile (n <= 4) {\n  total += n;\n  n++;\n}\nconsole.log(total);`, op: ['4', '10', '6', '15'], c: 1, exp: '1 + 2 + 3 + 4 = 10.' },
              { tipo: 'quiz', p: 'Por que este código trava?<pre>let x = 1;\nwhile (x < 5) {\n  console.log(x);\n}</pre>', op: ['Falta break', 'x nunca muda', 'while não aceita <', 'Falta ;'], c: 1, exp: 'Faltou x++ dentro do laço.' },
              { tipo: 'codigo', p: 'Contagem regressiva de 5 até 1 com <code>while</code>, depois mostre <code>Fogo!</code>', inicio: ``, saida: '5\n4\n3\n2\n1\nFogo!', usar: [['while', 'Use while']], dicas: ['let n = 5;', 'while (n >= 1) { console.log(n); n--; }', 'O "Fogo!" fica fora do laço'], sol: `let n = 5;\nwhile (n >= 1) {\n  console.log(n);\n  n--;\n}\nconsole.log("Fogo!");` },
              { tipo: 'codigo', p: 'Leia números até vir <code>0</code>, somando. Mostre <code>Soma: X</code>.', inicio: `let soma = 0;\n`, entrada: '5\n3\n2\n0', saida: '5\n3\n2\n0\nSoma: 10', testes: [{ entrada: '5\n3\n2\n0', saida: '5\n3\n2\n0\nSoma: 10' }, { entrada: '0', saida: '0\nSoma: 0' }], dicas: ['while (true) { const n = Number(prompt()); ... }', 'if (n === 0) break;', 'soma += n; e no fim console.log(`Soma: ${soma}`);'], sol: `let soma = 0;\nwhile (true) {\n  const n = Number(prompt());\n  if (n === 0) break;\n  soma += n;\n}\nconsole.log(\`Soma: \${soma}\`);` }
