              { tipo: 'codigo', p: 'Crie <code>ehPar(n)</code> que devolve true/false.', inicio: `function ehPar(n) {\n  // seu código\n}\n`, teste: `console.log(ehPar(4));\nconsole.log(ehPar(7));\nconsole.log(ehPar(0));`, saida: 'true\nfalse\ntrue', dicas: ['A comparação já é true ou false', 'return n % 2 === 0;'], sol: `function ehPar(n) {\n  return n % 2 === 0;\n}` },
              { tipo: 'codigo', p: 'Crie <code>media(notas)</code> que devolve a média de um array (use um laço para somar).', inicio: `function media(notas) {\n}\n`, teste: `console.log(media([7, 8, 9]));\nconsole.log(media([5, 6]));`, saida: '8\n5.5', dicas: ['let soma = 0; for (const n of notas) soma += n;', 'return soma / notas.length;'], sol: `function media(notas) {\n  let soma = 0;\n  for (const n of notas) soma += n;\n  return soma / notas.length;\n}` }
