              { tipo: 'quiz', p: 'Para que serve o package.json?', op: ['Guardar senhas', 'Descrever o projeto e listar as bibliotecas que ele usa', 'Deixar o código mais rápido', 'É o arquivo principal do site'], c: 1, exp: 'Ele guarda nome, scripts (npm start) e dependências do projeto.' },
              { tipo: 'codigo', p: 'Organize o código bagunçado: crie as funções <code>subtotal(itens)</code>, <code>frete(valor)</code> (grátis a partir de 200, senão 20) e <code>total(itens)</code> que usa as outras duas. Use a constante <code>FRETE_GRATIS_A_PARTIR</code>.', inicio: `const FRETE_GRATIS_A_PARTIR = 200;\n\n`, teste: `const carrinho = [{ preco: 80, qtd: 2 }, { preco: 15, qtd: 1 }];\nconsole.log(subtotal(carrinho), frete(subtotal(carrinho)), total(carrinho));\nconsole.log(total([{ preco: 100, qtd: 2 }]));`, saida: '175 20 195\n200', usar: [['FRETE_GRATIS_A_PARTIR', 'Use a constante FRETE_GRATIS_A_PARTIR']], dicas: ['function subtotal(itens) { return itens.reduce((s, i) => s + i.preco * i.qtd, 0); }', 'function frete(valor) { return valor >= FRETE_GRATIS_A_PARTIR ? 0 : 20; }', 'function total(itens) { const s = subtotal(itens); return s + frete(s); }'], sol: `const FRETE_GRATIS_A_PARTIR = 200;\n\nfunction subtotal(itens) {\n  return itens.reduce((s, i) => s + i.preco * i.qtd, 0);\n}\n\nfunction frete(valor) {\n  return valor >= FRETE_GRATIS_A_PARTIR ? 0 : 20;\n}\n\nfunction total(itens) {\n  const s = subtotal(itens);\n  return s + frete(s);\n}` }
